const express = require("express");
const db = require("../db");

const router = express.Router();

router.post("/", async (req, res) => {
  const idempotencyKey = req.headers["idempotency-key"];
  if (!idempotencyKey) {
    return res.status(400).json({ error: "idempotency-key header required" });
  }

  const existing = await db.query(
    "SELECT * FROM orders WHERE account_id = $1 AND idempotency_key = $2",
    [req.user.accountId, idempotencyKey]
  );

  if (existing.length) {
    return res.status(200).json(existing[0]);
  }

  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity, idempotency_key) VALUES ($1, $2, $3, $4) RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity, idempotencyKey]
  );
  res.status(201).json(row);
});

router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row) {
    return res.status(404).end();
  }
  res.json(row);
});

module.exports = router;

turns.text:
The write() function has a vulnerability if the connection drops mid-transaction.

**If the connection dies between BEGIN and COMMIT:**

1. The failing query throws an error, caught by the catch block
2. catch tries to ROLLBACK on a dead connection
3. That ROLLBACK query fails and throws, masking the original error
4. finally calls release() on the dead connection (which may fail silently or throw again)

The transaction is auto-rolled back by PostgreSQL when the connection closes, so data is safe. But the caller gets a misleading error instead of the real problem, and the error handling swallows information.

**Better approach:** Catch and ignore ROLLBACK failures since a dead connection can't be rolled back anyway.

```javascript
async function write(text, params) {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const res = await client.query(text, params);
    await client.query("COMMIT");
    return res.rows[0];
  } catch (err) {
    try {
      await client.query("ROLLBACK");
    } catch (rollbackErr) {
      // Connection is likely dead; ignore
    }
    throw err;
  } finally {
    client.release();
  }
}
```

This way the original error is preserved and propagates correctly.

