Looking at the write() function:

```javascript
async function write(text, params) {
  const client = await pool.connect();  // ← Connection acquired
  try {
    await client.query("BEGIN");        // ← Transaction starts
    const res = await client.query(text, params);
    await client.query("COMMIT");       // ← Committed
    return res.rows[0];
  } catch (err) {
    await client.query("ROLLBACK");     // ← Attempted rollback
    throw err;
  } finally {
    client.release();
  }
}
```

