const { Pool } = require("pg");

const pool = new Pool();

// Every read in the service goes through query(). Every write goes through
// write() — it exists so callers get the RETURNING row back in one shape and
// so there is exactly one place a transaction begins.
async function query(text, params) {
  const res = await pool.query(text, params);
  return res.rows;
}

async function write(text, params) {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const res = await client.query(text, params);
    await client.query("COMMIT");
    return res.rows[0];
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }
}

async function writeIdempotent(text, params, accountId, idempotencyKey) {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const cached = await client.query(
      "SELECT order_id FROM idempotency_keys WHERE account_id = $1 AND key = $2",
      [accountId, idempotencyKey]
    );
    if (cached.rows.length) {
      await client.query("COMMIT");
      const res = await client.query("SELECT * FROM orders WHERE id = $1", [cached.rows[0].order_id]);
      return res.rows[0];
    }
    const res = await client.query(text, params);
    await client.query(
      "INSERT INTO idempotency_keys (account_id, key, order_id) VALUES ($1, $2, $3)",
      [accountId, idempotencyKey, res.rows[0].id]
    );
    await client.query("COMMIT");
    return res.rows[0];
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }
}

module.exports = { query, write, writeIdempotent };

