const express = require("express");
const db = require("../db");

const router = express.Router();

router.patch("/:id", async (req, res) => {
  if (req.params.id !== req.user.accountId) return res.status(403).end();
  const account = await db.query(
    "SELECT deleted_at FROM accounts WHERE id = $1",
    [req.params.id]
  );
  if (!account.length || account[0].deleted_at) return res.status(403).end();
  const row = await db.write(
    "UPDATE accounts SET display_name = $1, billing_email = $2 WHERE id = $3 RETURNING *",
    [req.body.display_name, req.body.billing_email, req.params.id]
  );
  res.json(row);
});

router.delete("/:id", async (req, res) => {
  if (req.params.id !== req.user.accountId) return res.status(403).end();
  await db.write("UPDATE accounts SET deleted_at = now() WHERE id = $1 RETURNING id",
    [req.params.id]);
  res.status(204).end();
});

module.exports = router;

