const express = require("express");
const db = require("../db");

const router = express.Router();

router.post("/", async (req, res) => {
  const idempotencyKey = req.headers["idempotency-key"];
  if (!idempotencyKey) return res.status(400).json({ error: "idempotency-key header required" });
  const row = await db.writeIdempotent(
    "INSERT INTO orders (account_id, sku, quantity) VALUES ($1, $2, $3) RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity],
    req.user.accountId,
    idempotencyKey
  );
  res.status(201).json(row);
});

router.patch("/:id/cancel", async (req, res) => {
  const order = await db.query(
    "SELECT account_id FROM orders WHERE id = $1",
    [req.params.id]
  );
  if (!order.length || order[0].account_id !== req.user.accountId) return res.status(403).end();
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 RETURNING *",
    [req.params.id]
  );
  res.json(row);
});

module.exports = router;
